import {useScopedLoad} from './scoped-load.js';
import {EntityPicker} from './selectors.jsx';
import {useState} from 'preact/hooks';
import {Page,Field,Button,Notice,Empty,Loading} from '../../components/ui.jsx';
import {queryString} from '../../api.js';
import {useLiveUpdates} from '../../live.js';
import {activityTitle,activityChanges,feedParameters} from './activity-state.js';
export function LiveControl({live}) {
  return <div className="live-control"><span role="status">Updates: {live.status}</span>
    <Button onClick={()=>live.setPaused(!live.paused)}>{live.paused?'Resume live updates':'Pause live updates'}</Button>
    {live.lastEventAt&&<small>Last update {new Date(live.lastEventAt).toLocaleTimeString()}</small>}</div>;
}
export function ActivityEntry({event}) {
  const item=event.after??event.before??{};
  const issueId=event.entityType==='issue'?event.entityId:item.issueId;
  const changes=activityChanges(event);
  return <article className="activity-entry"><header>
    <strong>{issueId?<a href={'#/issues/'+encodeURIComponent(issueId)}>{activityTitle(event)}</a>:activityTitle(event)}</strong>
    <span>{event.entityType} {event.action.replaceAll('_',' ')}</span>
    <time dateTime={event.time}>{new Date(event.time).toLocaleString()}</time>
  </header>{changes.length>0&&<details><summary>{changes.length} field {changes.length===1?'change':'changes'}</summary>
    <dl>{changes.map(change=><div key={change.key}><dt>{change.label}</dt><dd><del>{String(change.before)}</del> → <span>{String(change.after)}</span></dd></div>)}</dl>
  </details>}</article>;
}
export function ActivityPage({api,query,navigate}) {
  const [draft,setDraft]=useState(()=>({orgId:query.orgId??'',projectId:query.projectId??'',issueId:query.issueId??'',userId:query.userId??'',entityType:query.entityType??'',action:query.action??'',from:query.from??'',to:query.to??''}));
  const [applied,setApplied]=useState(draft);
  const [cursor,setCursor]=useState('');
  const [history,setHistory]=useState([]);
  const load=useScopedLoad(JSON.stringify([applied,cursor]),()=>applied.orgId?api.get('/activity?'+queryString({...applied,cursor,limit:25})):Promise.resolve(null),[JSON.stringify(applied),cursor]);
  const live=useLiveUpdates({orgId:applied.orgId,projectId:applied.projectId,enabled:Boolean(applied.orgId),onActivity:()=>load.reload()});
  function submit(event){event.preventDefault();setApplied({...draft});setCursor('');setHistory([]);navigate('/activity?'+queryString(feedParameters(draft)));}
  function next(){setHistory([...history,cursor]);setCursor(load.data.nextCursor);}
  function previous(){setCursor(history.at(-1)??'');setHistory(history.slice(0,-1));}
  return <Page title="Activity"><form className="insight-filters" onSubmit={submit}>
    <EntityPicker api={api} type="organizations" label="Organization" value={draft.orgId} onChange={id=>setDraft({...draft,orgId:id,projectId:'',issueId:''})}/>
    <EntityPicker api={api} type="projects" orgId={draft.orgId} label="Project filter" value={draft.projectId} onChange={id=>setDraft({...draft,projectId:id,issueId:''})}/>
    <EntityPicker api={api} type="issues" orgId={draft.orgId} projectId={draft.projectId} label="Issue filter" value={draft.issueId} onChange={id=>setDraft({...draft,issueId:id})}/>
    <Field label="Actor ID" value={draft.userId} onInput={event=>setDraft({...draft,userId:event.currentTarget.value})}/>
    <Field label="Entity"><select value={draft.entityType} onChange={event=>setDraft({...draft,entityType:event.currentTarget.value})}><option value="">All events</option>{['issue','comment','relation','project','label','sprint','attachment','membership','team'].map(type=><option value={type}>{type}</option>)}</select></Field>
    <Field label="Action" value={draft.action} onInput={event=>setDraft({...draft,action:event.currentTarget.value})}/>
    <Field label="From (UTC)" type="datetime-local" value={draft.from.slice(0,16)} onInput={event=>setDraft({...draft,from:event.currentTarget.value?new Date(event.currentTarget.value+'Z').toISOString():''})}/>
    <Field label="To (UTC)" type="datetime-local" value={draft.to.slice(0,16)} onInput={event=>setDraft({...draft,to:event.currentTarget.value?new Date(event.currentTarget.value+'Z').toISOString():''})}/>
    <Button type="submit">Apply filters</Button>
  </form><Notice error={load.error}/>{applied.orgId?<>
    <LiveControl live={live}/>{load.loading?<Loading/>:load.data?.items.length?load.data.items.map(event=><ActivityEntry key={event.id} event={event}/>):<Empty>No matching activity. Changes appear here as the team works.</Empty>}
    <div className="pagination"><Button disabled={!history.length||load.loading} onClick={previous}>Previous</Button><Button disabled={!load.data?.nextCursor||load.loading} onClick={next}>Next</Button><Button busy={load.loading} onClick={load.reload}>Refresh</Button></div>
  </>:<Empty>Choose an organization to see its accessible activity.</Empty>}</Page>;
}

import {useScopedLoad} from './scoped-load.js';
import {useState} from 'preact/hooks';
import {Page,Field,Button,Notice,Empty,Loading} from '../../components/ui.jsx';
import {queryString} from '../../api.js';
import {useLiveUpdates} from '../../live.js';
import {LiveControl} from './activity.jsx';
import {BarChart,LineChart} from './charts.jsx';
import {EntityPicker} from './selectors.jsx';
const priorityNames=['No priority','Urgent','High','Normal','Low'];
export function DashboardPage({api,query,navigate}) {
  const [orgId,setOrgId]=useState(query.orgId??'');
  const [projectId,setProjectId]=useState(query.projectId??'');
  const [weeks,setWeeks]=useState('12');
  const [date,setDate]=useState('');
  const [sprintId,setSprintId]=useState('');
  const [unit,setUnit]=useState('issues');
  const [showIdeal,setShowIdeal]=useState(true);
  const [showScope,setShowScope]=useState(true);
  const [filters,setFilters]=useState({statusId:'',assigneeId:'',priority:'',overdue:''});
  const [issueCursor,setIssueCursor]=useState('');
  const [issueHistory,setIssueHistory]=useState([]);
  const report=useScopedLoad(JSON.stringify([orgId,projectId,weeks,date,sprintId,filters,issueCursor]),()=>orgId?api.get('/dashboard?'+queryString({orgId,projectId,weeks,date,sprintId,...filters,issueCursor})):Promise.resolve(null),[orgId,projectId,weeks,date,sprintId,JSON.stringify(filters),issueCursor]);
  const live=useLiveUpdates({orgId,projectId,enabled:Boolean(orgId),onActivity:()=>report.reload()});
  const data=report.data,valueKey=unit==='points'?'points':'count',burndown=data?.burndown;
  const series=[...(showScope?[{key:'scope',label:'Scope',color:'#8757c4'}]:[]),{key:'remaining',label:'Remaining',color:'#d96031'},...(showIdeal?[{key:'idealRemaining',label:'Ideal',color:'#4263c7',dashed:true}]:[])];
  function resetPage(){setIssueCursor('');setIssueHistory([]);}
  function filter(key,value){setFilters(previous=>({...previous,[key]:value}));resetPage();}
  function changeScope(org,project){setOrgId(org);setProjectId(project);setSprintId('');setFilters({statusId:'',assigneeId:'',priority:'',overdue:''});resetPage();}
  return <Page title="Dashboard">
    <form onSubmit={event=>{event.preventDefault();report.reload();navigate('/dashboard?'+queryString({orgId,projectId}));}}>
      <div className="insight-filters">
        <EntityPicker api={api} type="organizations" label="Organization" value={orgId} onChange={id=>changeScope(id,'')}/>
        <EntityPicker api={api} type="projects" orgId={orgId} label="Project scope" value={projectId} onChange={id=>changeScope(orgId,id)} placeholder="All accessible projects"/>
        <Field label="Reporting weeks" type="number" min="1" max="52" value={weeks} onChange={event=>setWeeks(event.currentTarget.value)}/>
        <Field label="Throughput ending date (UTC)" type="date" value={date} onChange={event=>setDate(event.currentTarget.value)}/>
        <Field label="Chart unit"><select value={unit} onChange={event=>setUnit(event.currentTarget.value)}><option value="issues">Issues</option><option value="points">Estimate points</option></select></Field>
        <Button type="submit">Refresh dashboard</Button>
      </div>
    </form>
    <Notice error={report.error}/>
    {!orgId?<Empty>Choose an organization to report on accessible projects.</Empty>:<>
      <LiveControl live={live}/>
      {report.loading?<Loading/>:data&&<>
        <section aria-label="Current issue filters">
          <h2>Current work</h2>
          <p>These counts and the issue table describe current filesystem-backed application records. The selected reference date affects overdue classification, not issue status history. Choose a chart group or filter below to inspect the current set.</p>
          <div className="insight-filters">
            <Field label="Status"><select value={filters.statusId} onChange={event=>filter('statusId',event.currentTarget.value)}><option value="">All statuses</option>{data.filterOptions.statuses.map(status=><option key={status.id} value={status.id}>{status.name}</option>)}</select></Field>
            <Field label="Assignee"><select value={filters.assigneeId} onChange={event=>filter('assigneeId',event.currentTarget.value)}><option value="">All assignees</option><option value="unassigned">Unassigned</option>{data.filterOptions.assignees.map(user=><option key={user.id} value={user.id}>{user.name}</option>)}</select></Field>
            <Field label="Priority"><select value={filters.priority} onChange={event=>filter('priority',event.currentTarget.value)}><option value="">All priorities</option>{priorityNames.map((name,index)=><option key={index} value={String(index)}>{name}</option>)}</select></Field>
            <label><input type="checkbox" checked={filters.overdue==='true'} onChange={event=>filter('overdue',event.currentTarget.checked?'true':'')}/> Overdue open work only</label>
            <Button type="button" onClick={()=>{setFilters({statusId:'',assigneeId:'',priority:'',overdue:''});resetPage();}}>Clear current-work filters</Button>
          </div>
          <div className="dashboard-grid" aria-label="Current matching issue totals">{[['Matching issues',data.totals.issues],['Open',data.totals.open],['Done',data.totals.done],['Unassigned',data.totals.unassigned],['Overdue',data.totals.overdue],['Estimate points',data.totals.points]].map(([label,value])=><article className="chart-panel" key={label}><h3>{label}</h3><strong>{value}</strong></article>)}</div>
          <div className="dashboard-grid">
            <BarChart id="status-chart" title="By workflow status" items={data.byStatus} valueKey={valueKey} unit={unit} selectedId={filters.statusId} onSelect={row=>filter('statusId',filters.statusId===row.id?'':row.id)}/>
            <BarChart id="assignee-chart" title="By assignee" items={data.byAssignee} valueKey={valueKey} unit={unit} selectedId={filters.assigneeId} onSelect={row=>filter('assigneeId',filters.assigneeId===(row.id??'unassigned')?'':row.id??'unassigned')}/>
            <BarChart id="priority-chart" title="By priority" items={data.byPriority.map(row=>({...row,name:priorityNames[row.priority]}))} valueKey={valueKey} unit={unit} selectedId={filters.priority===''?null:Number(filters.priority)} onSelect={row=>filter('priority',filters.priority===String(row.priority)?'':String(row.priority))}/>
          </div>
          <h3>Matching current issues</h3>
          {!data.issuePage.items.length?<Empty>No current issues match these filters.</Empty>:<div className="table-scroll"><table><thead><tr><th>Issue</th><th>Status</th><th>Assignee</th><th>Priority</th><th>Due date</th></tr></thead><tbody>{data.issuePage.items.map(issue=><tr key={issue.id}><td><a href={'#/issues/'+encodeURIComponent(issue.id)}>{issue.key} · {issue.title}</a></td><td>{issue.statusName}</td><td>{issue.assignee?.name??'Unassigned'}</td><td>{priorityNames[issue.priority]}</td><td>{issue.dueDate??'—'}</td></tr>)}</tbody></table></div>}
          <div className="pagination"><Button type="button" disabled={!issueHistory.length} onClick={()=>{setIssueCursor(issueHistory.at(-1));setIssueHistory(issueHistory.slice(0,-1));}}>Previous issues</Button><Button type="button" disabled={!data.issuePage.nextCursor} onClick={()=>{setIssueHistory([...issueHistory,issueCursor]);setIssueCursor(data.issuePage.nextCursor);}}>Next issues</Button></div>
        </section>
        <section aria-label="Historical throughput">
          <h2>Completion history</h2>
          <p>This series uses all visible issues in the selected project scope, independently of current-work status, assignee and priority filters. It counts distinct completion transitions per UTC week, once per issue/week. Selecting an old ending date does not substitute today's counts for historical status.</p>
          <LineChart id="throughput-chart" title="Weekly throughput" rows={data.throughput} unit={unit} series={[{key:unit==='points'?'points':'issues',label:'Completed',color:'#267d68'}]}/>
        </section>
        <section>
          <h2>Sprint burndown</h2>
          <Field label="Sprint"><select value={sprintId||burndown?.sprint.id||''} onChange={event=>setSprintId(event.currentTarget.value)}><option value="">Choose sprint</option>{data.sprints.map(sprint=><option key={sprint.id} value={sprint.id}>{sprint.name} · {sprint.status}</option>)}</select></Field>
          <label><input type="checkbox" checked={showIdeal} onChange={event=>setShowIdeal(event.currentTarget.checked)}/> Show ideal line</label>
          <label><input type="checkbox" checked={showScope} onChange={event=>setShowScope(event.currentTarget.checked)}/> Show scope line</label>
          {burndown?<><p>{burndown.sprint.name}: {burndown.changes} recorded scope/progress changes. Future actual values remain blank; missing estimates contribute zero points.</p><LineChart id="burndown-chart" title={burndown.sprint.name+' burndown'} rows={burndown.days} series={series}/></>:<Empty>Create a sprint to see its recorded daily burndown.</Empty>}
        </section>
      </>}
    </>}
  </Page>;
}

import {useScopedLoad} from './scoped-load.js';
import {useState} from 'preact/hooks';
import {Button,Notice,Empty,Loading} from '../../components/ui.jsx';
import {queryString} from '../../api.js';
import {useScopedAction} from './use-action.js';
export function DigestPanel({api,orgId}) {
  const [cursor,setCursor]=useState('');
  const [history,setHistory]=useState([]);
  const action=useScopedAction(orgId);
  const load=useScopedLoad(orgId+(typeof cursor==='undefined'?'':cursor),()=>api.get('/digests?'+queryString({orgId,cursor,limit:10})),[orgId,cursor]);
  function batch(){
    action.run(signal=>api.post('/digests',{orgId},{signal}),result=>{
      setCursor('');setHistory([]);load.reload();
      return result.count?'Queued '+result.count+' updates. '+result.remaining+' remain available for another deliberate batch.':'No new unread updates need a digest.';
    });
  }
  return <section>
    <h2>Email digests</h2>
    <p>Queue up to 200 new unread updates in your private local outbox. Batching preserves unread state. Invitation and reset messages never appear in this view.</p>
    <Button busy={action.busy} type="button" onClick={batch}>Queue unread digest</Button>
    <Notice error={action.error??load.error}/><Notice>{action.message}</Notice>
    {load.loading?<Loading/>:!load.data?.items.length?<Empty>No digests queued yet.</Empty>:load.data.items.map(digest=><details key={digest.id}>
      <summary>{new Date(digest.createdAt).toLocaleString()} · {digest.count} accessible updates</summary>
      <pre>{digest.textBody||'These updates are no longer accessible.'}</pre>
    </details>)}
    <div className="pagination">
      <Button type="button" disabled={!history.length||load.loading} onClick={()=>{setCursor(history.at(-1));setHistory(history.slice(0,-1));}}>Previous digests</Button>
      <Button type="button" disabled={!load.data?.nextCursor||load.loading} onClick={()=>{setHistory([...history,cursor]);setCursor(load.data.nextCursor);}}>Next digests</Button>
    </div>
  </section>;
}
export function Preferences({api,orgId}) {
  const load=useScopedLoad(orgId+(typeof cursor==='undefined'?'':cursor),()=>api.get('/notification-preferences?'+queryString({orgId})),[orgId]);
  const action=useScopedAction(orgId);
  function update(key,value){action.run(signal=>api.patch('/notification-preferences',{orgId,[key]:value},{signal}),()=>{load.reload();return 'Preferences saved.';});}
  return <section>
    <h2>Notification preferences</h2><Notice error={action.error??load.error}/><Notice>{action.message}</Notice>
    {load.loading?<Loading/>:load.data&&<div>
      <label><input type="checkbox" disabled={action.busy} checked={load.data.preferences.mentionsOnly} onChange={event=>update('mentionsOnly',event.currentTarget.checked)}/> Notify me only for explicit mentions</label>
      <label><input type="checkbox" disabled={action.busy} checked={load.data.preferences.emailEnabled} onChange={event=>update('emailEnabled',event.currentTarget.checked)}/> Enable email digest batching</label>
    </div>}
  </section>;
}

import {useScopedLoad} from './scoped-load.js';
import {useState} from 'preact/hooks';
import {Page,Field,Button,Notice,Empty,Loading} from '../../components/ui.jsx';
import {queryString} from '../../api.js';
import {useLiveUpdates} from '../../live.js';
import {LiveControl,ActivityEntry} from './activity.jsx';
import {notificationPath} from './activity-state.js';
import {EntityPicker} from './selectors.jsx';
import {WatchPanel} from './watch-panel.jsx';
import {DigestPanel,Preferences} from './digest-panel.jsx';
import {useScopedAction} from './use-action.js';
export function InboxPage({api,query,navigate}) {
  const [orgId,setOrgId]=useState(query.orgId??''),[state,setState]=useState('all'),[projectId,setProjectId]=useState('');
  const [cursor,setCursor]=useState(''),[history,setHistory]=useState([]),[selected,setSelected]=useState(new Set());
  const action=useScopedAction(orgId+':'+projectId+':'+state);
  const load=useScopedLoad(JSON.stringify([orgId,state,projectId,cursor]),()=>orgId?api.get('/notifications?'+queryString({orgId,state,projectId,cursor,limit:25})):Promise.resolve(null),[orgId,state,projectId,cursor]);
  const live=useLiveUpdates({orgId,projectId,enabled:Boolean(orgId),onActivity:()=>load.reload()});
  function reset(){action.reset();setCursor('');setHistory([]);setSelected(new Set());}
  function mark(read,ids,all=false){
    action.run(signal=>api.post('/notifications/mark',{orgId,read,...(all?{all:true}:{ids})},{signal}),()=>{setSelected(new Set());load.reload();return 'Inbox updated.';});
  }
  function markOne(item){
    action.run(signal=>api.patch('/notifications/'+encodeURIComponent(item.id),{read:!item.read},{signal}),()=>{load.reload();return item.read?'Marked unread.':'Marked read.';});
  }
  return <Page title="Inbox"><form className="insight-filters" onSubmit={event=>{event.preventDefault();reset();load.reload();navigate('/inbox?'+queryString({orgId}));}}>
    <EntityPicker api={api} type="organizations" label="Organization" value={orgId} onChange={id=>{reset();setOrgId(id);setProjectId('');}}/>
    <Field label="State"><select value={state} onChange={event=>{setState(event.currentTarget.value);reset();}}><option value="all">All</option><option value="unread">Unread</option><option value="read">Read</option></select></Field>
    <EntityPicker api={api} type="projects" orgId={orgId} label="Project filter" value={projectId} onChange={id=>{reset();setProjectId(id);}}/><Button type="submit">Refresh inbox</Button>
  </form><Notice error={action.error??load.error}/><Notice>{action.message}</Notice>
  {orgId?<><LiveControl live={live}/><p role="status">{load.data?.unread??0} unread updates</p>
    <div className="insight-actions"><Button busy={action.busy} disabled={!selected.size} onClick={()=>mark(true,[...selected])}>Mark selected read</Button><Button busy={action.busy} disabled={!selected.size} onClick={()=>mark(false,[...selected])}>Mark selected unread</Button>
      <Button busy={action.busy} disabled={!load.data?.unread} onClick={()=>mark(true,null,true)}>Mark all read in this organization</Button></div>
    {load.loading?<Loading/>:!load.data?.items.length?<Empty>No {state==='all'?'':state+' '}updates match this inbox. Follow issues or projects to receive activity.</Empty>:load.data.items.map(item=><article key={item.id} data-testid={'notification-'+item.id} className={'notification-row '+(item.read?'read':'unread')}>
      <label><input aria-label={'Select notification '+item.id} type="checkbox" checked={selected.has(item.id)} onChange={event=>{const next=new Set(selected);event.currentTarget.checked?next.add(item.id):next.delete(item.id);setSelected(next);}}/></label>
      <div className="content"><a href={'#'+notificationPath(item)}>Open {item.activity.entityType}</a> · {item.reason}<ActivityEntry event={item.activity}/></div>
      <Button busy={action.busy} onClick={()=>markOne(item)}>{item.read?'Mark unread':'Mark read'}</Button>
    </article>)}
    <div className="pagination"><Button disabled={!history.length||load.loading} onClick={()=>{setCursor(history.at(-1));setHistory(history.slice(0,-1));setSelected(new Set());}}>Previous</Button>
      <Button disabled={!load.data?.nextCursor||load.loading} onClick={()=>{setHistory([...history,cursor]);setCursor(load.data.nextCursor);setSelected(new Set());}}>Next</Button></div>
    <details><summary>Watches, preferences and email digests</summary><Preferences key={'preferences-'+orgId} api={api} orgId={orgId}/><WatchPanel key={'watch-'+orgId} api={api} orgId={orgId}/><DigestPanel key={'digest-'+orgId} api={api} orgId={orgId}/></details>
  </>:<Empty>Choose an organization to open your personal inbox.</Empty>}</Page>;
}

import {useLoad} from '../../components/ui.jsx';
export function scopedResult(state,scope) {
  const matching=state.data?.scope===scope;
  return {data:matching?state.data.data:null,error:matching?state.data.error:null,loading:state.loading||!matching,reload:state.reload};
}
export function useScopedLoad(scope,load,deps=[]) {
  const state=useLoad(async()=>{
    try{return {scope,data:await load(),error:null};}
    catch(error){return {scope,data:null,error};}
  },[scope,...deps]);
  return scopedResult(state,scope);
}

import {useScopedLoad} from './scoped-load.js';
import {useEffect,useId,useState} from 'preact/hooks';
import {Button,Notice} from '../../components/ui.jsx';
import {queryString} from '../../api.js';
import {pickerScope,emptyPicker,scopedPicker,pickerAction,selectedOption,optionDescription} from './selector-state.js';
export function EntityPicker({api,type,orgId,projectId,permission='insight:read',value='',onChange,label,required=false,disabled=false,placeholder='Choose an item'}) {
  const scope=pickerScope({type,orgId,projectId,permission});
  const [saved,setSaved]=useState(()=>emptyPicker(scope));
  const state=scopedPicker(saved,scope),fieldId=useId();
  const enabled=!disabled&&(type==='organizations'||Boolean(orgId));
  const parameters={type,orgId:type==='organizations'?undefined:orgId,projectId,permission};
  const load=useScopedLoad(JSON.stringify([scope,state.query,state.cursor,enabled]),()=>enabled?api.get('/insight/options?'+queryString({...parameters,q:state.query,cursor:state.cursor,limit:20})):Promise.resolve({items:[],total:0,nextCursor:null}),[scope,state.query,state.cursor,enabled]);
  const selected=useScopedLoad(JSON.stringify([scope,value,enabled]),()=>enabled&&value?api.get('/insight/options?'+queryString({...parameters,id:value,limit:1})):Promise.resolve({items:[]}),[scope,value,enabled]);
  useEffect(()=>{if(saved.scope!==scope)setSaved(emptyPicker(scope));},[scope]);
  const items=load.loading?[]:load.data?.items??[];
  const current=selectedOption(items,value,selected.loading?null:selected.data);
  function dispatch(action){setSaved(previous=>pickerAction(scopedPicker(previous,scope),action));}
  function choose(event){const id=event.currentTarget.value;onChange?.(id,items.find(item=>item.id===id)??current);}
  return <fieldset className="entity-picker" disabled={!enabled}>
    <legend>{label}</legend>
    <div className="picker-search"><label htmlFor={fieldId+'-search'}>Search {label.toLowerCase()}</label>
      <input id={fieldId+'-search'} type="search" autoComplete="off" value={state.draft} onInput={event=>dispatch({type:'draft',value:event.currentTarget.value})} onKeyDown={event=>{if(event.key==='Enter'){event.preventDefault();dispatch({type:'search'});}}}/>
      <Button type="button" onClick={()=>dispatch({type:'search'})}>Search</Button>
    </div>
    <Notice error={load.error??selected.error}/>
    <label htmlFor={fieldId+'-results'} className="sr-only">{label} search results</label>
    <select id={fieldId+'-results'} size="5" value={value} required={required} aria-busy={load.loading} aria-describedby={fieldId+'-status'} onChange={choose}>
      <option value="" disabled={required}>{placeholder}</option>
      {value&&!items.some(item=>item.id===value)&&<option value={value}>{current?.label??(selected.loading?'Loading selected item…':'Selected item is unavailable')}</option>}
      {items.map(item=><option key={item.id} value={item.id}>{item.label}{item.archived?' (archived)':''}</option>)}
    </select>
    <p id={fieldId+'-status'} role="status">{!enabled?'Choose an organization first.':load.loading?'Loading options…':load.error?'Options could not be loaded.':load.data?.total===0?'No matching accessible items.':(load.data?.total??0)+' matching accessible items.'}</p>
    {current&&<p className="picker-selection">Selected: {optionDescription(current)}</p>}
    <div className="pagination"><Button type="button" disabled={!state.history.length||load.loading} onClick={()=>dispatch({type:'previous'})}>Previous {label.toLowerCase()}</Button>
      <Button type="button" disabled={!load.data?.nextCursor||load.loading} onClick={()=>dispatch({type:'next',cursor:load.data.nextCursor})}>Next {label.toLowerCase()}</Button>
      <Button type="button" busy={load.loading} onClick={()=>{load.reload();selected.reload();}}>Reload options</Button>
      {!required&&value&&<Button type="button" onClick={()=>onChange?.('',null)}>Clear selection</Button>}
    </div>
  </fieldset>;
}

import {useScopedLoad} from './scoped-load.js';
import {useState} from 'preact/hooks';
import {Field,Button,Notice,Empty,Loading} from '../../components/ui.jsx';
import {queryString} from '../../api.js';
import {EntityPicker} from './selectors.jsx';
import {useScopedAction} from './use-action.js';
export function WatchPanel({api,orgId}) {
  const [type,setType]=useState('issue');
  const [targetId,setTargetId]=useState('');
  const [cursor,setCursor]=useState('');
  const [history,setHistory]=useState([]);
  const action=useScopedAction(orgId);
  const load=useScopedLoad(JSON.stringify([orgId,cursor]),()=>api.get('/subscriptions?'+queryString({orgId,cursor,limit:20})),[orgId,cursor]);
  const target=useScopedLoad(JSON.stringify([orgId,type,targetId]),()=>targetId?api.get('/subscriptions?'+queryString({orgId,targetType:type,targetId,limit:1})):Promise.resolve({items:[]}),[orgId,type,targetId]);
  const watched=target.data?.items?.find(item=>item.targetType===type&&item.targetId===targetId);
  function changed(){load.reload();target.reload();}
  function watch(event){
    event.preventDefault();
    action.run(signal=>api.post('/subscriptions',{targetType:type,targetId},{signal}),()=>{changed();return 'You are now watching this '+type+'.';});
  }
  function mute(item){
    action.run(signal=>api.delete('/subscriptions/'+item.targetType+'/'+encodeURIComponent(item.targetId),undefined,{signal}),()=>{changed();return 'Ordinary updates from this '+item.targetType+' are muted.';});
  }
  return <section>
    <h2>Watching</h2>
    <p>Look up an issue or project by key or title. Creators, assignees and mentioned people follow an issue automatically. Muting stops ordinary watcher updates; direct mentions remain visible.</p>
    <form onSubmit={watch}>
      <Field label="Watch type"><select value={type} onChange={event=>{setType(event.currentTarget.value);setTargetId('');action.reset();}}><option value="issue">Issue</option><option value="project">Project</option></select></Field>
      <EntityPicker key={type} api={api} type={type==='issue'?'issues':'projects'} orgId={orgId} value={targetId} label={type==='issue'?'Issue to watch':'Project to watch'} required onChange={id=>{setTargetId(id);action.reset();}}/>
      {target.loading&&targetId?<Loading/>:targetId&&<p role="status">{watched?'Currently watching ('+(watched.manual?'manual':watched.reason)+').':'You are not currently watching this target.'}</p>}
      <Button busy={action.busy} disabled={!targetId||Boolean(watched?.manual)} type="submit">{watched?'Keep watching manually':'Watch'}</Button>
      {watched&&<Button busy={action.busy} type="button" onClick={()=>mute(watched)}>Mute selected {type}</Button>}
    </form>
    <Notice error={action.error??load.error??target.error}/><Notice>{action.message}</Notice>
    {load.loading?<Loading/>:!load.data?.items.length?<Empty>No watches in this organization.</Empty>:<ul className="watch-list">{load.data.items.map(item=><li key={item.id}>
      <a href={'#/'+(item.targetType==='issue'?'issues/':'projects/')+encodeURIComponent(item.targetId)}>{item.target?.label??item.targetId}</a>
      <span> · {item.manual?'manually watched':item.reason}</span>
      <Button busy={action.busy} type="button" onClick={()=>mute(item)}>Mute</Button>
    </li>)}</ul>}
    <div className="pagination">
      <Button type="button" disabled={!history.length||load.loading} onClick={()=>{setCursor(history.at(-1));setHistory(history.slice(0,-1));}}>Previous watches</Button>
      <Button type="button" disabled={!load.data?.nextCursor||load.loading} onClick={()=>{setHistory([...history,cursor]);setCursor(load.data.nextCursor);}}>Next watches</Button>
    </div>
  </section>;
}

import assert from 'node:assert/strict';
import {readFile} from 'node:fs/promises';
async function nextFrame(reader,state) {
  for(;;){const at=state.text.indexOf('\n\n');if(at>=0){const frame=state.text.slice(0,at);state.text=state.text.slice(at+2);const lines=frame.split('\n');return {event:lines.find(line=>line.startsWith('event: '))?.slice(7),data:JSON.parse(lines.find(line=>line.startsWith('data: ')).slice(6))};}const chunk=await reader.read();if(chunk.done)throw new Error('Live stream ended before required update');state.text+=state.decoder.decode(chunk.value,{stream:true});}
}
export async function smoke(ctx) {
  const {ids,api,check}=ctx;
  await check('activity feed and explicit personal watch use canonical issue events',async()=>{
    const feed=await api('GET','/activity?'+new URLSearchParams({orgId:ids.orgId,projectId:ids.projectId,issueId:ids.issueId}));
    assert.ok(feed.items.some(event=>event.entityType==='issue'&&event.entityId===ids.issueId));
    const watch=(await api('POST','/subscriptions',{targetType:'project',targetId:ids.projectId})).subscription;
    assert.equal(watch.targetId,ids.projectId);assert.equal(watch.manual,true);
    assert.ok((await api('GET','/subscriptions?orgId='+ids.orgId)).items.some(item=>item.targetId===ids.issueId));
  });
  await check('owner mention produces unread inbox with reversible exact owned read state',async()=>{
    const inbox=await api('GET','/notifications?orgId='+ids.orgId);
    const notification=inbox.items.find(item=>item.activity.entityType==='comment'&&item.activity.entityId===ids.mentionCommentId);
    assert.ok(notification);assert.equal(notification.reason,'mention');assert.equal(notification.read,false);
    ids.browserNotificationId=notification.id;
    assert.equal((await api('PATCH','/notifications/'+notification.id,{read:true})).notification.read,true);
    assert.equal((await api('PATCH','/notifications/'+notification.id,{read:false})).notification.readAt,null);
    assert.equal((await ctx.request('PATCH','/notifications/'+notification.id,{read:true},{actor:'member'})).status,404);
  });
  await check('real authenticated SSE receives a member mutation and cleans up its stream',async()=>{
    const client=ctx.clients.owner,controller=new AbortController();const timer=setTimeout(()=>controller.abort(),4000);
    let reader;
    try{
      const headers=client.token?{authorization:'Bearer '+client.token}:{cookie:client.cookie};
      const response=await fetch(ctx.url+'/api/v1/events?orgId='+ids.orgId,{headers,signal:controller.signal});assert.equal(response.status,200);
      reader=response.body.getReader();const state={text:'',decoder:new TextDecoder()};assert.equal((await nextFrame(reader,state)).event,'ready');
      const comment=(await api('POST','/issues/'+ids.issueId+'/comments',{body:'Live acceptance @[Owner](user:'+ctx.clients.owner.user.id+')'},'member')).comment;
      ids.liveCommentId=comment.id;
      const event=await nextFrame(reader,state);assert.equal(event.event,'activity');assert.equal(event.data.entityId,comment.id);assert.equal(event.data.after.issueId,ids.issueId);
    }finally{clearTimeout(timer);controller.abort();if(reader)await reader.cancel().catch(()=>{});}
  });
  await check('digest batches private unread updates once and preserves browser notification state',async()=>{
    const created=await api('POST','/digests',{orgId:ids.orgId});assert.ok(created.count>=2);assert.equal((await api('POST','/digests',{orgId:ids.orgId})).count,0);
    const digests=await api('GET','/digests?orgId='+ids.orgId);assert.ok(digests.items.some(row=>row.id===created.digest.id));ids.digestId=created.digest.id;
    const live=(await api('GET','/notifications?orgId='+ids.orgId)).items.find(item=>item.activity.entityId===ids.liveCommentId);assert.ok(live);ids.inboxReadNotificationId=live.id;
    await api('POST','/notifications/mark',{ids:[live.id],read:true});
    const browser=(await api('GET','/notifications?orgId='+ids.orgId)).items.find(item=>item.id===ids.browserNotificationId);assert.equal(browser.read,false);
  });
  await check('actual feed inbox preferences and digest CLI families use scoped authentication',async()=>{
    assert.ok((await ctx.cli(['feed','list','--org',ids.orgId,'--issue',ids.issueId])).items.length);
    assert.ok((await ctx.cli(['inbox','list','--org',ids.orgId,'--state','unread'])).items.some(item=>item.id===ids.browserNotificationId));
    assert.equal((await ctx.cli(['inbox','preferences','--org',ids.orgId])).preferences.emailEnabled,true);
    assert.ok((await ctx.cli(['inbox','digests','--org',ids.orgId])).items.some(item=>item.id===ids.digestId));
  });
}
export async function restart(ctx) {
  await ctx.check('activity watches inbox read and unread state and digests survive restart',async()=>{
    const {ids,api}=ctx;const inbox=await api('GET','/notifications?orgId='+ids.orgId);
    assert.equal(inbox.items.find(item=>item.id===ids.browserNotificationId).read,false);
    assert.equal(inbox.items.find(item=>item.id===ids.inboxReadNotificationId).read,true);
    assert.ok((await api('GET','/activity?orgId='+ids.orgId+'&issueId='+ids.issueId)).items.some(event=>event.entityId===ids.liveCommentId));
